namespace cp_algo::math{template<typename T>struct poly_t;template<typename T>std::array<poly_t<T>,2>divmod(poly_t<T>p,poly_t<T>const&q);template<typename T>struct poly_t{using Vector=big_vector<T>;using base=T;Vector a;poly_t&normalize(){while(deg()>=0&&lead()==base(0)){a.pop_back();}return*this;}poly_t()=default;poly_t(T a0):a{a0}{normalize();}poly_t(Vector const&t):a(t){normalize();}poly_t(Vector&&t):a(std::move(t)){normalize();}poly_t&negate_inplace(){std::ranges::transform(a,begin(a),std::negate{});return*this;}friend poly_t operator-(poly_t p){p.negate_inplace();return p;}poly_t&operator+=(poly_t const&t){a.resize(std::max(size(a),size(t.a)));std::ranges::transform(a,t.a,begin(a),std::plus{});return normalize();}poly_t&operator-=(poly_t const&t){a.resize(std::max(size(a),size(t.a)));std::ranges::transform(a,t.a,begin(a),std::minus{});return normalize();}friend poly_t operator+(poly_t p,poly_t const&t){p+=t;return p;}friend poly_t operator-(poly_t p,poly_t const&t){p-=t;return p;}poly_t&mod_xk_inplace(size_t k){a.resize(std::min(size(a),k));return normalize();}poly_t&mul_xk_inplace(size_t k){if(is_zero()){return*this;}a.insert(begin(a),k,T(0));return normalize();}poly_t&div_xk_inplace(int64_t k){if(k<0){return mul_xk_inplace(-k);}a.erase(begin(a),begin(a)+std::min<size_t>(k,size(a)));return normalize();}poly_t&substr_inplace(size_t l,size_t k){return mod_xk_inplace(l+k).div_xk_inplace(l);}poly_t mod_xk(size_t k)const&{return substr(0,k);}poly_t mod_xk(size_t k)&&{mod_xk_inplace(k);return std::move(*this);}poly_t mul_xk(size_t k)const&{auto p=*this;p.mul_xk_inplace(k);return p;}poly_t mul_xk(size_t k)&&{mul_xk_inplace(k);return std::move(*this);}poly_t div_xk(int64_t k)const&{return k<0?mul_xk(-k):substr(k,a.size());}poly_t div_xk(int64_t k)&&{div_xk_inplace(k);return std::move(*this);}poly_t substr(size_t l,size_t k)const&{l=std::min(l,a.size());k=std::min(k,a.size()-l);return Vector(begin(a)+l,begin(a)+l+k);}poly_t substr(size_t l,size_t k)&&{substr_inplace(l,k);return std::move(*this);}poly_t&operator*=(const poly_t&t){fft::mul(a,t.a);normalize();return*this;}friend poly_t operator*(poly_t p,const poly_t&t){p*=t;return p;}poly_t&operator/=(const poly_t&t){assert(!t.is_zero());if(this==&t){return*this=T(1);}auto[q,r]=divmod(std::move(*this),t);return*this=std::move(q);}poly_t&operator%=(const poly_t&t){assert(!t.is_zero());if(this==&t){a.clear();return*this;}auto[q,r]=divmod(std::move(*this),t);return*this=std::move(r);}friend poly_t operator/(poly_t p,poly_t const&t){p/=t;return p;}friend poly_t operator%(poly_t p,poly_t const&t){p%=t;return p;}poly_t&operator*=(T const&x){for(auto&it:a){it*=x;}return normalize();}poly_t&operator/=(T const&x){return*this*=x.inv();}friend poly_t operator*(poly_t p,T const&x){p*=x;return p;}friend poly_t operator/(poly_t p,T const&x){p/=x;return p;}poly_t&reverse(size_t n){a.resize(n);std::ranges::reverse(a);return normalize();}poly_t&reverse(){return reverse(size(a));}poly_t reversed(size_t n)const&{auto p=*this;p.reverse(n);return p;}poly_t reversed(size_t n)&&{reverse(n);return std::move(*this);}poly_t reversed()const&{return reversed(a.size());}poly_t reversed()&&{reverse();return std::move(*this);}friend poly_t operator*(T const&x,poly_t p){p*=x;return p;}poly_t negx()const{auto res=*this;for(int i=1;i<=deg();i+=2){res.a[i]=-res[i];}return res;}void print(int n)const{for(int i=0;i<n;i++){std::cout<<(*this)[i]<<' ';}std::cout<<"\n";}void print()const{print(deg()+1);}T eval(T x)const{T res(0);for(int i=deg();i>=0;i--){res*=x;res+=a[i];}return res;}T lead()const{assert(!is_zero());return a.back();}int deg()const{return(int)a.size()-1;}bool is_zero()const{return a.empty();}T operator[](int idx)const{return idx<0||idx>deg()?T(0):a[idx];}T&coef(size_t idx){return a[idx];}bool operator==(const poly_t&t)const{return a==t.a;}bool operator!=(const poly_t&t)const{return a!=t.a;}size_t trailing_xk()const{if(is_zero()){return-1;}int res=0;while(a[res]==T(0)){res++;}return res;}poly_t&mul_truncate(poly_t const&t,size_t k){fft::mul_truncate(a,t.a,k);return normalize();}static poly_t xk(size_t n){return poly_t(T(1)).mul_xk(n);}static poly_t ones(size_t n){return Vector(n,1);}poly_t x2()const{Vector res(2*a.size());for(size_t i=0;i<a.size();i++){res[2*i]=a[i];}return res;}std::array<poly_t,2>bisect(size_t n)const{n=std::min(n,size(a));Vector res[2];for(size_t i=0;i<n;i++){res[i%2].push_back(a[i]);}return{std::move(res[0]),std::move(res[1])};}std::array<poly_t,2>bisect()const{return bisect(size(a));}};}
